import dormqr = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = new Float64Array( 2 );
	const TAU = new Float64Array( 1 );
	const C = new Float64Array( 6 );
	const WORK = new Float64Array( 3 );

	dormqr( 'row-major', 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK, 3 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a valid layout...
{
	const A = new Float64Array( 2 );
	const TAU = new Float64Array( 1 );
	const C = new Float64Array( 6 );
	const WORK = new Float64Array( 3 );

	dormqr( 5, 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormqr( true, 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormqr( false, 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormqr( null, 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormqr( void 0, 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormqr( [], 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormqr( {}, 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK, 3 ); // $ExpectError
	dormqr( ( x: number ): number => x, 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK, 3 ); // $ExpectError
}

