	dormqr( 'row-major', 'left', 'no-transpose', 2, 3, 1, A, 1 ); // $ExpectError
	dormqr( 'row-major', 'left', 'no-transpose', 2, 3, 1, A, 1, TAU ); // $ExpectError
	dormqr( 'row-major', 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C ); // $ExpectError
	dormqr( 'row-major', 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3 ); // $ExpectError
	dormqr( 'row-major', 'left', 'no-transpose', 2, 3, 1, A, 1, TAU, C, 3, WORK ); // $ExpectError
